+import test from "node:test";
+import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { openStore } from "../src/db/store.js";
+import { app } from "./helpers.js";
+
+test("seed has schema 3 sites and annex-fridge location", () => {
+  const { store } = app();
+  assert.equal(store.data.schemaVersion, 3);
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  const annex = store.data.sites.find((s) => s.id === "annex");
+  assert.equal(annex.name, "Annex kitchen");
+  const annexFridge = store.data.locations.find((l) => l.id === "annex-fridge");
+  assert.deepEqual(annexFridge, { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+});
+
+test("older schema 2 data file opens cleanly", () => {
+  const dbPath = new URL("../data/db.json", import.meta.url).pathname;
+  const raw = JSON.parse(readFileSync(dbPath, "utf8"));
+  assert.equal(raw.schemaVersion, 2);
+  const store = openStore(dbPath);
+  assert.equal(store.data.schemaVersion, 3);
+  assert.ok(store.data.locations.every((l) => l.site === "main"));
+});
+
+test("unknown site returns 400 unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "X-Larder-Site": "roof" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("items, suppliers, recipes and dishes are shared; stock, batches, cooking, alerts, stock value and stock-takes are site-scoped", async () => {
+  const { handle, store } = app();
+  const annexHeader = { "X-Larder-Site": "annex" };
+
+  // Empty annex stock initially, shared items/suppliers/dishes visible.
+  const annexItems = await handle({ path: "/items", headers: annexHeader });
+  assert.equal(annexItems.status, 200);
+  assert.equal(annexItems.body.length, 6);
+  assert.ok(annexItems.body.every((i) => i.onHand === 0));
+  assert.equal((await handle({ path: "/suppliers", headers: annexHeader })).body.length, 2);
+  assert.equal((await handle({ path: "/dishes", headers: annexHeader })).body.length, 3);
+  assert.equal((await handle({ path: "/recipes/2/cost", headers: annexHeader })).status, 200);
+
+  // Annex cannot see or waste main batches.
+  assert.deepEqual((await handle({ path: "/batches", headers: annexHeader })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annexHeader })).status, 404);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: annexHeader, body: { qty: 1 } })).status, 404);
+
+  // Annex stock value is 0; cooking fails with not_enough_stock; alerts show no annex expiring batches and all items low.
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annexHeader })).body.totalCents, 0);
+  assert.equal((await handle({ method: "POST", path: "/recipes/2/cook", headers: annexHeader, body: { portions: 5 } })).status, 409);
+  const annexAlerts0 = (await handle({ path: "/alerts", headers: annexHeader })).body;
+  assert.deepEqual(annexAlerts0.expiring, []);
+  assert.equal(annexAlerts0.lowStock.length, 6);
+
+  // Receive an order into annex-fridge for bechamel ingredients (milk=2, butter=3, flour=4).
+  const orderRes = await handle({
+    method: "POST",
+    path: "/orders",
