+      supplierId: 1,
+      lines: [
+        { itemId: 2, qty: 2 },
+        { itemId: 3, qty: 1 },
+        { itemId: 4, qty: 1 },
+      ],
+    },
+  });
+  await handle({ method: "POST", path: `/orders/${orderRes.body.id}/send` });
+  const rec = await handle({
+    method: "POST",
+    path: `/orders/${orderRes.body.id}/receive`,
+    body: {
+      lots: [
+        { lot: "AX-MILK", expires: "2026-10-30", location: "annex-fridge" },
+        { lot: "AX-BUTTER", expires: "2026-12-01", location: "annex-fridge" },
+        { lot: "AX-FLOUR", expires: "2027-01-01", location: "annex-fridge" },
+      ],
+    },
+  });
+  assert.equal(rec.status, 200);
+  const [milkBatch] = rec.body.batches;
+
+  // Main still doesn't see annex batches or stock.
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.equal((await handle({ path: `/batches/${milkBatch.id}` })).status, 404);
+  assert.ok(!(await handle({ path: "/alerts" })).body.expiring.some((b) => b.id === milkBatch.id));
+
+  // Annex sees its own batches, item onHand, alerts, stock value, and can cook using annex stock only.
