+  assert.equal(annexMilk.batches.length, 1);
+  assert.equal((await handle({ path: "/batches", headers: annexHeader })).body.length, 3);
+  assert.equal((await handle({ path: "/alerts", headers: annexHeader })).body.expiring.length, 1);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annexHeader })).body.totalCents, 2 * 129 + 945 + 85);
+
+  const mainBatchesBeforeCook = JSON.stringify(store.data.batches.filter((b) => b.location !== "annex-fridge"));
+  const cooked = await handle({ method: "POST", path: "/recipes/2/cook", headers: annexHeader, body: { portions: 5 } });
+  assert.equal(cooked.status, 200);
+  assert.equal(JSON.stringify(store.data.batches.filter((b) => b.location !== "annex-fridge")), mainBatchesBeforeCook);
+  assert.equal((await handle({ path: "/items/2", headers: annexHeader })).body.onHand, 1);
+
+  // Stock-takes are site-scoped: annex cannot open for "fridge", main cannot open for "annex-fridge" or count/finish annex take.
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: annexHeader, body: { location: "fridge" } })).status, 400);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annexHeader, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: milkBatch.id, counted: 0.5 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annexHeader, body: { batchId: milkBatch.id, counted: 0.5 } })).status, 200);
+  const finished = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annexHeader });
+  assert.equal(finished.status, 200);
+  assert.deepEqual(finished.body.lines, [{ batchId: milkBatch.id, expected: 1, counted: 0.5, diff: -0.5 }]);
